async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error('通信エラー '+r.status);return r.json()}
async function searchPlaces(q){const m=q.match(/^\s*(-?\d+(?:\.\d+)?)\s*[,、]\s*(-?\d+(?:\.\d+)?)\s*$/);if(m){const lat=+m[1],lon=+m[2];if(Math.abs(lat)>85||Math.abs(lon)>180)throw Error('緯度・経度の範囲を確認してください');return [{name:q,coord:[lon,lat]}]}const presets={'小倉駅':{name:'小倉駅',coord:[130.882544,33.8868979]},'行橋駅':{name:'行橋駅',coord:[130.9707,33.7287]},'博多駅':{name:'博多駅',coord:[130.4206,33.5897]}};if(presets[q])return [presets[q]];const prefecture=start?.name.match(/^(.+?[都道府県])/u)?.[1]||'福岡県',shortName=q.length<=6&&!/[都道府県市町村駅]/u.test(q),queries=shortName?[prefecture+q+'市',q]:[q];const lists=await Promise.all(queries.map(async term=>{try{return await json('https://msearch.gsi.go.jp/address-search/AddressSearch?q='+encodeURIComponent(term))}catch(e){if(term===q)throw e;return []}}));const anchor=start?.coord||[130.882544,33.8868979],seen=new Set(),items=lists.flat().map(p=>({name:p.properties.title,coord:p.geometry.coordinates})).filter(p=>{const key=p.name+'|'+p.coord.join(',');if(seen.has(key))return false;seen.add(key);return true});const rank=p=>(p.name===q||p.name===prefecture+q+'市'?0:p.name.startsWith(prefecture)?1:2),distance=p=>(p.coord[0]-anchor[0])**2+(p.coord[1]-anchor[1])**2;return items.sort((a,b)=>rank(a)-rank(b)||distance(a)-distance(b)).slice(0,16);}
