async function highSpeedSegments(coords){if($('shinkansen').value==='no')return [];try{const xs=coords.map(p=>p[0]),ys=coords.map(p=>p[1]);const box=[Math.min(...ys)-.012,Math.min(...xs)-.012,Math.max(...ys)+.012,Math.max(...xs)+.012];const query='[out:json][timeout:18];way["railway"="rail"]["highspeed"="yes"]('+box.join(',')+');out geom;';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),11000);let response;try{response=await fetch('https://overpass.kumi.systems/api/interpreter',{method:'POST',body:'data='+encodeURIComponent(query),headers:{'Content-Type':'application/x-www-form-urlencoded'},signal:controller.signal})}finally{clearTimeout(timer)}if(!response.ok)return [];const data=await response.json();return(data.elements||[]).filter(e=>e.geometry?.length>1).map(e=>e.geometry.map(p=>[p.lon,p.lat]))}catch(e){console.warn('新幹線線路の判定を省略',e);return []}}
function nearHighSpeed(c,segments){const x=c[0],y=c[1],scale=Math.cos(y*Math.PI/180);for(const line of segments)for(let i=1;i<line.length;i++){const a=line[i-1],b=line[i],dx=(b[0]-a[0])*scale,dy=b[1]-a[1],d=dx*dx+dy*dy;if(!d)continue;const t=Math.max(0,Math.min(1,((x-a[0])*scale*dx+(y-a[1])*dy)/d));if(Math.hypot((x-a[0])*scale-t*dx,y-a[1]-t*dy)<.0015)return true}return false}
function shinkansenMatchSummary(){const rail=travelLegs.filter(l=>l.mode==='rail');let hit=0,total=0;for(const leg of rail){if(!leg.highSpeed?.length)continue;const step=Math.max(1,Math.floor(leg.coords.length/150));for(let i=0;i<leg.coords.length;i+=step){total++;if(nearHighSpeed(leg.coords[i],leg.highSpeed))hit++}}return {hit,total}}
function updateShinkansenStatus(){const rail=travelLegs.filter(l=>l.mode==='rail');const el=$('railRouteInfo');if(!el||!travelLegs.some(l=>l.mode==='rail'))return;if($('shinkansen').value==='no'){if(rail.every(l=>l.usedProfile==='mlit-local')){el.textContent='🚃 鹿児島本線 小倉駅〜博多駅｜在来線の線路に沿うルート';return}if(rail.every(l=>l.usedProfile==='osm-local')){el.textContent='🚃 在来線の線路データを直接たどった経路（新幹線を除外）';return}el.textContent=rail.every(l=>l.usedProfile==='non_tgv')?'🚃 在来線向け検索を使用（経路の確認を推奨）':'⚠ 在来線向け検索が失敗したため、全線検索で代替しました';return}if(rail.some(l=>l.usedProfile==='all_tracks')){el.textContent='⚠ 新幹線優先検索が失敗したため全線検索で代替。🚅区間は地図と照合中';return}if(rail.every(l=>l.usedProfile==='mlit-shinkansen'||l.usedProfile==='osm-shinkansen')){el.textContent='🚅 山陽新幹線 小倉駅～博多駅｜新幹線の線路に沿うルート';return}const result=shinkansenMatchSummary();el.textContent=result.hit?'🚅 新幹線線路と一致する地点 '+result.hit+'件を確認。該当区間で🚅、その他は🚃':'🚃 新幹線の線路と一致する区間は確認できませんでした（新幹線利用は未確定）'}
function isStationNamed(p,name){return String(p.name||'').replace(/^(福岡県|北九州市|福岡市)/g,'').includes(name)}
async function fetchRailOSM(query,timeout=18000){
 const mirrors=['https://overpass.kumi.systems/api/interpreter','https://overpass.nchc.org.tw/api/interpreter','https://overpass.private.coffee/api/interpreter'];
 const errors=[];
 for(const url of mirrors){try{const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),timeout);let res;try{res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'data='+encodeURIComponent(query),signal:ctrl.signal})}finally{clearTimeout(timer)}if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();if(!Array.isArray(data.elements))throw Error('線路データ形式が不正');return data}catch(e){errors.push(e.message)}}
 throw Error('線路データサーバーに接続できません（'+errors.join('／')+'）')
}
async function kokuraHakataRail(ps){if($('shinkansen').value!=='yes'||ps.length!==2)return null;const a=ps[0],b=ps[1];const forward=isStationNamed(a,'小倉駅')&&isStationNamed(b,'博多駅');const backward=isStationNamed(a,'博多駅')&&isStationNamed(b,'小倉駅');if(!forward&&!backward)return null;
// 山陽新幹線の小倉～博多間。OSMの高速鉄道線路を直接取得し、端点を接続して経路を構築する。
const west=[130.420,33.560],east=[130.900,33.910];
const query='[out:json][timeout:24];way["railway"="rail"]["highspeed"="yes"](33.55,130.40,33.93,130.92);out geom;';
const data=await fetchRailOSM(query,14000),ways=(data.elements||[]).filter(e=>e.geometry?.length>1).map(e=>e.geometry.map(p=>[p.lon,p.lat]));
if(!ways.length)throw Error('山陽新幹線の線路データが見つかりません');
const startCoord=forward?a.coord:b.coord,endCoord=forward?b.coord:a.coord;
const nodes=new Map(),adj=new Map(),key=p=>p.map(n=>n.toFixed(5)).join(',');
for(const line of ways){for(let i=1;i<line.length;i++){const p=line[i-1],q=line[i],u=key(p),v=key(q),w=directKm(p,q);nodes.set(u,p);nodes.set(v,q);if(!adj.has(u))adj.set(u,[]);if(!adj.has(v))adj.set(v,[]);adj.get(u).push([v,w]);adj.get(v).push([u,w])}}
const nearest=c=>{let best='',d=Infinity;for(const [k,p] of nodes){const n=directKm(c,p);if(n<d){d=n;best=k}}return {key:best,km:d}};
const from=nearest(startCoord),to=nearest(endCoord);if(from.km>3||to.km>3)throw Error('新幹線の駅付近の線路を確認できません');
const dist=new Map([[from.key,0]]),prev=new Map(),queue=[[0,from.key]];let iterations=0;
while(queue.length&&iterations++<30000){queue.sort((a,b)=>b[0]-a[0]);const [d,u]=queue.pop();if(d!==dist.get(u))continue;if(u===to.key)break;for(const [v,w] of adj.get(u)||[]){const next=d+w;if(next<(dist.get(v)??Infinity)){dist.set(v,next);prev.set(v,u);queue.push([next,v])}}}
if(!dist.has(to.key))throw Error('小倉～博多間の新幹線線路が接続されていません');
const path=[];for(let at=to.key;at;at=prev.get(at)){path.push(nodes.get(at));if(at===from.key)break}path.reverse();
const km=dist.get(to.key);if(km<45||km>80)throw Error('新幹線の経路距離が不自然です（'+km.toFixed(1)+'km）');
const coords=forward?path:path.reverse();return {mode:'rail',coords,meters:km*1000,highSpeed:ways,usedProfile:'osm-shinkansen'}
}
async function localRailFromOSM(ps){
if($('shinkansen').value!=='no'||ps.length!==2)return null;
const a=ps[0].coord,b=ps[1].coord,km=directKm(a,b);if(km>120) return null;
const pad=.035,box=[Math.min(a[1],b[1])-pad,Math.min(a[0],b[0])-pad,Math.max(a[1],b[1])+pad,Math.max(a[0],b[0])+pad];
const query='[out:json][timeout:35];way["railway"="rail"]["highspeed"!="yes"]["service"!~"^(yard|siding|spur)$"]('+box.join(',')+');out geom;';
const data=await fetchRailOSM(query,22000),ways=(data.elements||[]).filter(e=>e.geometry?.length>1).map(e=>e.geometry.map(p=>[p.lon,p.lat]));if(!ways.length)throw Error('在来線の線路データがありません');
const nodes=new Map(),adj=new Map(),key=p=>p.map(n=>n.toFixed(5)).join(',');
for(const line of ways)for(let i=1;i<line.length;i++){const p=line[i-1],q=line[i],u=key(p),v=key(q),w=directKm(p,q);nodes.set(u,p);nodes.set(v,q);if(!adj.has(u))adj.set(u,[]);if(!adj.has(v))adj.set(v,[]);adj.get(u).push([v,w]);adj.get(v).push([u,w])}
const nearest=c=>{let best='',d=Infinity;for(const [k,p] of nodes){const n=directKm(c,p);if(n<d){d=n;best=k}}return {key:best,km:d}};
const from=nearest(a),to=nearest(b);if(from.km>1.5||to.km>1.5)throw Error('指定駅に接続する在来線が見つかりません');
const distances=new Map([[from.key,0]]),previous=new Map(),heap=[];const push=(d,k)=>{heap.push([d,k]);let i=heap.length-1;while(i>0){const p=(i-1)>>1;if(heap[p][0]<=d)break;heap[i]=heap[p];i=p}heap[i]=[d,k]};const pop=()=>{const top=heap[0],last=heap.pop();if(heap.length){let i=0;while(2*i+1<heap.length){let c=2*i+1;if(c+1<heap.length&&heap[c+1][0]<heap[c][0])c++;if(heap[c][0]>=last[0])break;heap[i]=heap[c];i=c}heap[i]=last}return top};push(0,from.key);
while(heap.length){const [d,u]=pop();if(d!==distances.get(u))continue;if(u===to.key)break;for(const [v,w] of adj.get(u)||[]){const nd=d+w;if(nd<(distances.get(v)??Infinity)){distances.set(v,nd);previous.set(v,u);push(nd,v)}}}
if(!distances.has(to.key))throw Error('指定駅をつなぐ在来線が見つかりません');
const path=[];for(let at=to.key;at;at=previous.get(at)){path.push(nodes.get(at));if(at===from.key)break}path.reverse();const length=distances.get(to.key);if(km>10&&length>km*1.55)throw Error('在来線の経路が遠回りです（'+length.toFixed(1)+'km）');
return {mode:'rail',coords:path,meters:length*1000,highSpeed:[],usedProfile:'osm-local'}
}

