function verifiedKokuraHakata(ps){
 if(ps.length!==2)return null;
 const forward=isStationNamed(ps[0],'小倉駅')&&isStationNamed(ps[1],'博多駅');
 const reverse=isStationNamed(ps[0],'博多駅')&&isStationNamed(ps[1],'小倉駅');
 if(!forward&&!reverse)return null;
 const high=$('shinkansen').value==='yes',data=verifiedRail[high?'high':'local'];
 const coords=reverse?data.coords.slice().reverse():data.coords.slice();
 if(directKm(coords[0],ps[0].coord)>1||directKm(coords.at(-1),ps[1].coord)>1)return null;
 const track=measured(coords);
 return {mode:'rail',coords,meters:track.total*111195,highSpeed:high?[coords]:[],trainType:high?'shinkansen':'local',usedProfile:high?'mlit-shinkansen':'mlit-local',labels:data.labels.filter(item=>coords.some(c=>directKm(c,item.coord)<.35))};
}
async function travelLeg(ps,mode){if(mode==='rail'){const verified=verifiedKokuraHakata(ps);if(verified)return verified;const base='https://routing.openrailrouting.org/route?points_encoded=false&'+ps.map(p=>'point='+p.coord[1]+','+p.coord[0]).join('&');const wanted=$('shinkansen').value==='yes'?'tgv_all':'non_tgv';say('鉄道ルート検索中：'+(wanted==='tgv_all'?'新幹線あり':'在来線のみ')+'（'+ps[0].name+' → '+ps.at(-1).name+'）');const profiles=[wanted];const direct=directKm(ps[0].coord,ps.at(-1).coord);const failures=[];for(const profile of profiles){try{const data=await Promise.race([json(base+'&profile='+profile),new Promise((_,reject)=>setTimeout(()=>reject(Error('検索時間切れ')),profile===wanted?8500:14000))]);const path=data.paths?.[0];if(!path?.points?.coordinates?.length)throw Error(data.message||'経路なし');const coords=path.points.coordinates;const forward=directKm(coords[0],ps[0].coord)+directKm(coords.at(-1),ps.at(-1).coord);const reverse=directKm(coords[0],ps.at(-1).coord)+directKm(coords.at(-1),ps[0].coord);const railCoords=reverse+.5<forward?coords.slice().reverse():coords;const first=directKm(railCoords[0],ps[0].coord),last=directKm(railCoords.at(-1),ps.at(-1).coord);if(first>1.5||last>1.5)throw Error('出発駅・到着駅から線路が離れています');const endpoints=directKm(railCoords[0],railCoords.at(-1));if(direct>15&&endpoints<direct*.75)throw Error('検索した線路が目的地まで到達していません');const km=path.distance/1000;if(direct>15&&km>direct*1.65)throw Error('大きく遠回りする経路 '+km.toFixed(1)+'km（直線'+direct.toFixed(1)+'km）');return {mode,coords:railCoords,meters:path.distance,highSpeed:[],usedProfile:profile}}catch(e){failures.push(profile+': '+e.message)}}throw Error('正しい鉄道経路を確認できませんでした。'+failures.join('／')+'。駅名を再指定してください。')}const server=new URL($('router').value);if(server.protocol!=='https:')throw Error('ルート検索サーバーはhttpsを指定してください');const data=await json(server.href.replace(/\/$/,'')+'/route/v1/driving/'+ps.map(p=>p.coord.join(',')).join(';')+'?overview=full&geometries=geojson');if(data.code!=='Ok'||!data.routes?.[0])throw Error('道路ルートが見つかりません。道路上の地点を選び直してください。');return {mode,coords:data.routes[0].geometry.coordinates,meters:data.routes[0].distance}}
async function prepareTravel(){const ps=points(),mode=$('transport').value;if(mode==='mixed'&&!vias.length)throw Error('鉄道＋車では経由地に乗り換え駅を追加してください。');const modes=[...$('legModes').querySelectorAll('select')].map(el=>el.value);travelLegs=mode==='mixed'?await Promise.all(ps.slice(1).map((p,i)=>travelLeg([ps[i],p],modes[i]||'car'))):[await travelLeg(ps,mode)];for(const leg of travelLegs)leg.track=measured(leg.coords);const car=travelLegs.filter(l=>l.mode==='car').reduce((s,l)=>s+l.meters,0),rail=travelLegs.filter(l=>l.mode==='rail').reduce((s,l)=>s+l.meters,0);distanceText='直線距離 '+directKm(start.coord,end.coord).toFixed(1)+' km'+(car?' ／ 道路距離 '+(car/1000).toFixed(1)+' km':'')+(rail?' ／ 鉄道距離 '+(rail/1000).toFixed(1)+' km':'');$('distanceInfo').textContent=distanceText;$('distanceInfo').hidden=false;return travelLegs.flatMap(l=>l.coords)}
let intermediateLabels=[],recordingNow=false;
async function findIntermediateLabels(){
 intermediateLabels=[];if(!travelLegs.length)return;
 if(travelLegs.every(l=>l.labels)){intermediateLabels=travelLegs.flatMap(l=>l.labels).map(item=>({...item,at:routeFractionFor(item.coord)})).sort((a,b)=>a.at-b.at);return;}
 const seen=new Set(points().map(p=>p.name.replace(/(駅|市|町|区)$/u,'')));
 const samples=[];for(const leg of travelLegs){const count=Math.min(7,Math.max(2,Math.round(leg.meters/70000)));for(let i=1;i<count;i++){const coord=part(i/count,leg.track).c;samples.push({coord,mode:leg.mode})}}
 await Promise.all(samples.slice(0,12).map(async sample=>{try{const [lon,lat]=sample.coord;const data=await json('https://mreversegeocoder.gsi.go.jp/reverse-geocoder/LonLatToAddress?lat='+lat+'&lon='+lon);const code=data.results?.muniCd;let name='';if(code){const table=window.GSI?.MUNI_ARRAY;const entry=table?.[code];if(entry)name=entry.split(',').at(-1)}if(!name&&data.results?.lv01Nm)name=data.results.lv01Nm;if(!name)return;name=name.replace(/^(.*?[都道府県])/u,'').replace(/(市|区|町|村).*/u,'$1');const key=name.replace(/(駅|市|町|区)$/u,'');if(seen.has(key))return;seen.add(key);intermediateLabels.push({...sample,name})}catch(e){console.warn('地名取得失敗',e)}}));
 // 鉄道区間ではOpenStreetMapの駅データを経路付近から取得する（失敗時は地名だけ表示）。
 for(const leg of travelLegs.filter(l=>l.mode==='rail')){
  try{
   const pts=leg.coords.filter((_,i)=>i%Math.max(1,Math.ceil(leg.coords.length/150))===0);
   const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);const bbox=[Math.min(...ys)-.025,Math.min(...xs)-.025,Math.max(...ys)+.025,Math.max(...xs)+.025];
   const query='[out:json][timeout:12];(node["railway"="station"]('+bbox.join(',')+');node["railway"="halt"]('+bbox.join(',')+'););out body;';
   const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),14000);
   let data;try{const response=await fetch('https://overpass.kumi.systems/api/interpreter',{method:'POST',body:new URLSearchParams({data:query}),signal:controller.signal});if(!response.ok)throw Error('駅データ取得失敗');data=await response.json()}finally{clearTimeout(timer)}
   const candidates=(data.elements||[]).filter(e=>e.tags?.name&&Number.isFinite(e.lon)&&Number.isFinite(e.lat)).map(e=>{const coord=[e.lon,e.lat];let best=Infinity,index=0;for(let i=0;i<pts.length;i++){const d=directKm(coord,pts[i]);if(d<best){best=d;index=i}}return {coord,name:e.tags['name:ja']||e.tags.name,near:best,index}}).filter(e=>e.near<2.5).sort((a,b)=>a.index-b.index);
   const chosen=[];for(const item of candidates){const key=item.name.replace(/駅$/u,'');if(seen.has(key)||chosen.some(x=>x.name===item.name||Math.abs(x.index-item.index)<Math.max(2,pts.length/9)))continue;chosen.push(item);seen.add(key)}
   const maxStations=6,step=Math.max(1,Math.ceil(chosen.length/maxStations));for(const item of chosen.filter((_,i)=>i%step===0).slice(0,maxStations))intermediateLabels.push({coord:item.coord,name:item.name.endsWith('駅')?item.name:item.name+'駅',mode:'rail'});
  }catch(e){console.warn('主要駅名の取得を省略しました',e)}
 }
 intermediateLabels.forEach(item=>item.at=routeFractionFor(item.coord));
 intermediateLabels.sort((a,b)=>{const aa=travelLegs[0].track.coords[0],bb=travelLegs.at(-1).track.coords.at(-1);return a.at-b.at});
}
function routeFractionFor(coord){let total=0,best=Infinity,at=0;for(const leg of travelLegs){const tr=leg.track;for(let i=1;i<tr.coords.length;i++){const a=tr.coords[i-1],b=tr.coords[i],dx=(b[0]-a[0])*Math.cos(coord[1]*Math.PI/180),dy=b[1]-a[1],px=(coord[0]-a[0])*Math.cos(coord[1]*Math.PI/180),py=coord[1]-a[1],q=Math.max(0,Math.min(1,(px*dx+py*dy)/Math.max(1e-14,dx*dx+dy*dy))),projection=[a[0]+(b[0]-a[0])*q,a[1]+(b[1]-a[1])*q],d=directKm(coord,projection);if(d<best){best=d;at=total+tr.lengths[i-1]+(tr.lengths[i]-tr.lengths[i-1])*q}}total+=tr.total}return total?at/total:0}
function updateLiveLabels(progress){let layer=$('passingLabels');if(!layer){layer=document.createElement('div');layer.id='passingLabels';layer.style.cssText='position:absolute;inset:0;pointer-events:none;overflow:hidden;z-index:8';$('mapStage').append(layer)}layer.replaceChildren();if(!travelLegs.length)return;const occupied=[];for(const item of intermediateLabels){const at=item.at??routeFractionFor(item.coord);if(progress<at-.05||progress>at+.2)continue;const p=map.project(item.coord),w=$('mapStage').clientWidth,h=$('mapStage').clientHeight;if(p.x<15||p.y<15||p.x>w-15||p.y>h-40)continue;const x=Math.max(8,Math.min(w-110,p.x+12)),y=Math.max(8,Math.min(h-35,p.y-32));if(occupied.some(q=>Math.abs(q.x-x)<105&&Math.abs(q.y-y)<27))continue;occupied.push({x,y});const el=document.createElement('div');el.textContent=item.name;el.style.cssText='position:absolute;left:'+x+'px;top:'+y+'px;max-width:105px;padding:3px 6px;border-radius:4px;background:rgba(255,255,255,.94);color:#17213a;font:600 11px sans-serif;white-space:nowrap;box-shadow:0 1px 4px #0005;opacity:'+Math.max(0,Math.min(1,(progress-at+.05)/.02,(at+.2-progress)/.03));layer.append(el)}}
function paintIntermediateLabels(ctx,c,placed){if(!intermediateLabels.length)return;const sx=c.width/map.getContainer().clientWidth,sy=c.height/map.getContainer().clientHeight;ctx.save();ctx.font='500 '+Math.max(12,Math.round(c.width*.012))+'px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';for(const item of intermediateLabels){const at=item.at??routeFractionFor(item.coord),progress=Number($('progress').value)||0;if(progress<at-.05||progress>at+.2)continue;ctx.globalAlpha=Math.max(0,Math.min(1,(progress-at+.05)/.02,(at+.2-progress)/.03));const xy=map.project(item.coord),x=xy.x*sx,y=xy.y*sy;if(x<20||y<20||x>c.width-20||y>c.height-65)continue;const w=ctx.measureText(item.name).width+12,h=23;const candidates=[[x+14,y-32],[x-w-14,y-32],[x+14,y+14],[x-w-14,y+14]];const rect=candidates.map(([rx,ry])=>({x:rx,y:ry,w,h})).find(r=>r.x>5&&r.y>5&&r.x+w<c.width-5&&r.y+h<c.height-55&&!placed.some(q=>r.x<q.x+q.w+8&&r.x+r.w+8>q.x&&r.y<q.y+q.h+8&&r.y+r.h+8>q.y));if(!rect)continue;placed.push(rect);ctx.fillStyle='rgba(255,255,255,.86)';ctx.fillRect(rect.x,rect.y,w,h);ctx.fillStyle='#24364b';ctx.fillText(item.name,rect.x+w/2,rect.y+h/2)}ctx.globalAlpha=1;ctx.restore()}
function vehicleHead(leg,p){return {coord:part(p,leg.track).c,mode:leg.mode,trainType:leg.mode==='rail'&&(leg.trainType==='shinkansen'||nearHighSpeed(part(p,leg.track).c,leg.highSpeed||[]))?'shinkansen':'local',from:part(Math.max(0,p-.002),leg.track).c,to:part(Math.min(1,p+.002),leg.track).c}}
function travelFrame(progress){if(!travelLegs.length){map.routeSegments=null;map.travelFrame=null;return}const total=travelLegs.reduce((s,l)=>s+l.track.total,0),target=total*progress;let consumed=0,head=null;map.routeSegments=travelLegs.map(l=>{const p=Math.max(0,Math.min(1,(target-consumed)/Math.max(.000001,l.track.total))),cut=part(p,l.track);if(!head&&target<=consumed+l.track.total)head=vehicleHead(l,p);consumed+=l.track.total;return {coords:p>0?cut.coords:[],color:l.mode==='rail'?'#159447':'#e44945'}});map.travelFrame=head||vehicleHead(travelLegs.at(-1),1)}
$('shinkansen').onchange=()=>{ready=false;$('preview').disabled=$('export').disabled=true;say('新幹線の利用設定を変更しました。地図とルートを準備してください。')};$('transport').onchange=()=>{$('shinkansenOption').hidden=$('transport').value==='car';paintLegs();ready=false;$('preview').disabled=$('export').disabled=true;say('移動手段を変更しました。地図とルートを準備してください。')};

function sourceStyle(){return {version:8,sources:{world:{type:'raster',tiles:['https://cyberjapandata.gsi.go.jp/xyz/std/{z}/{x}/{y}.png'],tileSize:256,minzoom:2,maxzoom:6,attribution:'地理院タイル'},road:{type:'raster',tiles:['https://cyberjapandata.gsi.go.jp/xyz/pale/{z}/{x}/{y}.png'],tileSize:256,minzoom:5,maxzoom:18,attribution:'地理院タイル'},photo:{type:'raster',tiles:['https://cyberjapandata.gsi.go.jp/xyz/seamlessphoto/{z}/{x}/{y}.jpg'],tileSize:256,minzoom:2,maxzoom:18,attribution:'地理院タイル'},terrain:{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],tileSize:256,maxzoom:15,encoding:'terrarium',attribution:'AWS Terrain Tiles'}},layers:[{id:'world',type:'raster',source:'world'},{id:'road',type:'raster',source:'road',minzoom:5,paint:{'raster-fade-duration':0}},{id:'photo',type:'raster',source:'photo',layout:{visibility:'none'},paint:{'raster-fade-duration':0}}]}}
try{if(!window.maplibregl)throw Error('地図ライブラリを読み込めません。再読み込みしてください。');map=new maplibregl.Map({container:'map',style:sourceStyle(),center:[130.94,33.8],zoom:10,canvasContextAttributes:{preserveDrawingBuffer:true},preserveDrawingBuffer:true,attributionControl:true});map.on('load',()=>{loaded=true;baseStyle('photo');map.addSource('route',{type:'geojson',data:{type:'Feature',geometry:{type:'LineString',coordinates:[]}}});map.addLayer({id:'route-line',type:'line',source:'route',paint:{'line-color':'#e44945','line-width':6},layout:{'line-cap':'round','line-join':'round'}})});map.on('click',e=>{if(!running)add({name:'指定地点（'+e.lngLat.lat.toFixed(5)+', '+e.lngLat.lng.toFixed(5)+'）',coord:[e.lngLat.lng,e.lngLat.lat]})});map.on('error',e=>{if(e.error?.message?.includes('Failed to initialize'))say('地図を表示できません：'+e.error.message)})}catch(e){say(e.message)}paint();
