function part(p,track=route){p=Math.max(0,Math.min(1,p));const target=track.total*p;let i=1;while(i<track.lengths.length-1&&track.lengths[i]<target)i++;let a=track.coords[i-1],b=track.coords[i],d=track.lengths[i]-track.lengths[i-1],q=d?(target-track.lengths[i-1])/d:0;const c=[a[0]+(b[0]-a[0])*q,a[1]+(b[1]-a[1])*q];return {c,coords:[...track.coords.slice(0,i),c]}}
function smooth(p){p=Math.max(0,Math.min(1,p));return p*p*(3-2*p)}
function mix(a,b,p){return a.map((v,i)=>v+(b[i]-v)*p)}
function pose(t){const center=bounds.getCenter().toArray(),target=end.coord,style=settings.style,place=settings.kind==='place';if(style==='auto'){if(t<.22){const p=smooth(t/.22);return {center:mix([138,37],[131,33],p),zoom:4+3*p,pitch:0,style:'road',progress:0}}if(t<.4){const p=smooth((t-.22)/.18);return {center:mix([131,33],center,p),zoom:7+(baseZoom-7)*p,pitch:0,style:'road',progress:0}}if(t<.8&&!place){const progress=(t-.4)/.4;return {center:settings.camera==='follow'?part(progress).c:center,zoom:settings.camera==='follow'?Math.min(16,Math.max(13,baseZoom+2)):baseZoom,pitch:0,style:'road',progress}}const p=smooth((t-(place?.4:.8))/(place?.6:.2));return {center:mix(center,target,p),zoom:baseZoom+(15-baseZoom)*p,pitch:50*p,style:'3d',progress:1}}if(place){const p=smooth(t);return {center:mix([138,37],target,p),zoom:4+11*p,pitch:style==='3d'?55*p:0,style,progress:1}}const q=part(t);return {center:settings.camera==='follow'?q.c:center,zoom:settings.camera==='follow'?Math.min(16,Math.max(13,baseZoom+2)):baseZoom,pitch:style==='3d'?50:0,style,progress:t}}
let currentArea='',areaRequests=new Map(),lastAreaKey='',muniPromise=null;
function loadMunicipalities(){window.GSI=window.GSI||{};if(window.GSI.MUNI_ARRAY&&Object.keys(window.GSI.MUNI_ARRAY).length)return Promise.resolve();window.GSI.MUNI_ARRAY=window.GSI.MUNI_ARRAY||{};if(muniPromise)return muniPromise;muniPromise=new Promise(resolve=>{const script=document.createElement('script');script.src='https://maps.gsi.go.jp/js/muni.js';script.onload=resolve;script.onerror=resolve;document.head.appendChild(script)});return muniPromise}
function cityOnly(name){const v=String(name||'').replace(/^(?:.+?[都道府県])/,'');const m=v.match(/^(.+?市)/);if(m)return m[1];const t=v.match(/^(.+?[町村])/);return t?t[1]:''}
function areaNameFromReverse(data){const code=String(data?.results?.muniCd||'');const table=window.GSI?.MUNI_ARRAY;const raw=table?.[code]||table?.[String(Number(code))];if(!raw)return '';const parts=raw.split(',');const pref=parts[1]||'',city=cityOnly(parts[3]||parts[2]||'')||cityOnly(parts[2]||'');return pref&&city?pref+city:''}
function showCurrentArea(progress){const label=$('currentArea');if(!label||!route||!route.total)return;const coord=part(progress).c,key=coord.map(n=>Math.round(n*50)/50).join(',');if(key===lastAreaKey)return;lastAreaKey=key;label.textContent=currentArea||'県・市を取得中…';const cached=areaRequests.get(key);if(typeof cached==='string'){currentArea=cached;label.textContent=cached;return}if(cached===null)return;areaRequests.set(key,null);const url='https://mreversegeocoder.gsi.go.jp/reverse-geocoder/LonLatToAddress?lat='+coord[1]+'&lon='+coord[0];Promise.allSettled([loadMunicipalities(),fetch(url).then(r=>r.json())]).then(async results=>{const data=results[1].status==='fulfilled'?results[1].value:null;let name=areaNameFromReverse(data);if(!name&&data?.results?.muniCd){const code=String(data.results.muniCd);try{const res=await fetch('https://www.land.mlit.go.jp/webland/api/CitySearch?area='+code.slice(0,2));const json=await res.json();const city=json?.data?.find(x=>String(x.id)===code);if(city)name=city.name}catch(e){}}if(name){areaRequests.set(key,name);if(lastAreaKey===key){currentArea=name;label.textContent=name}}else{areaRequests.delete(key);if(lastAreaKey===key)label.textContent=currentArea||'県・市を取得できません'}}).catch(()=>{areaRequests.delete(key);if(lastAreaKey===key)label.textContent=currentArea||'県・市を取得できません'})}
